void Pins::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/pins/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinsanalyticsGetRequest(req, res, auth);
    });
    svr.Get("/pins/{pin_id}/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinspinIdanalyticsGetRequest(req, res, auth);
    });
    svr.Post("/pins", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinsPostRequest(req, res, auth);
    });
    svr.Delete("/pins/{pin_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinspinIdDeleteRequest(req, res, auth);
    });
    svr.Get("/pins/{pin_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinspinIdGetRequest(req, res, auth);
    });
    svr.Get("/pins", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinsGetRequest(req, res, auth);
    });
    svr.Post("/pins/{pin_id}/save", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinspinIdsavePostRequest(req, res, auth);
    });
    svr.Patch("/pins/{pin_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handlePinspinIdPatchRequest(req, res, auth);
    });
}

